var a=`1280-bakes`;var n=`world-1280`;var t=`GD`;var r=`central-america-caribbean`;var s=8;var o=43;var u={en:`Bakes`,ua:`Гренадські смажені коржики`};var d={en:`Bakes is a dish from Grenada featuring all-purpose flour, baking powder, guava. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Гренадські смажені коржики, страва кухні країни Гренада з такими основними складниками: пшеничне борошно універсальне, розпушувач тіста, гуава. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,470,`g`],[`baking-powder`,15,`g`],[`table-salt`,7,`g`],[`water`,260,`ml`],[`unsalted-butter`,45,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,850,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`guava`,100,`g`]]}];var l={slug:a,id:n,country:`GD`,region:r,servings:8,minutes:43,title:u,text:d,steps:g};export{t as country,l as default,n as id,o as minutes,r as region,s as servings,a as slug,g as steps,d as text,u as title};